const swiper = new Swiper(".mySwiper", {
    slidesPerView: 1,
    spaceBetween: 10,
    speed: 1000,
    watchSlidesProgress: true,
    navigation: {
        nextEl: ".swiper-button-next",
        prevEl: ".swiper-button-prev",
    },
    pagination: {
        el: ".swiper-pagination",
        type: "progressbar",
    },

    on: {
        init(swiper) {
            updateSlides(swiper);
        },

        setTranslate(swiper) {
            updateSlides(swiper);
        },

        setTransition(swiper, duration) {
            swiper.slides.forEach(slide => {
                slide.style.setProperty(
                    "--effect-duration",
                    `${duration}ms`
                );
            });
        },

        touchStart(swiper) {
            swiper.slides.forEach(slide => {
                slide.style.setProperty("--effect-duration", "0ms");
            });
        }
    }
});
function updateSlides(swiper) {
    swiper.slides.forEach(slide => {

        const progress = Math.min(
            Math.abs(slide.progress),
            1
        );

        const opacity = progress;

        slide.style.setProperty(
            "--overlay-opacity",
            opacity
        );

        slide.style.setProperty(
            "--border-opacity",
            progress
        );

        const r = Math.round(255 + (162 - 255) * progress);
        const g = Math.round(255 + (144 - 255) * progress);
        const b = Math.round(255 + (95 - 255) * progress);

        slide.style.setProperty(
            "--slide-text-color",
            `rgb(${r}, ${g}, ${b})`
        );
    });
}

$(document).ready(function () {

    // Menu
    $('.burger').click(function () {
        $('.header__menu').addClass('header__menu--active')
        $('body').addClass('fixed-body')
    })

    $('.burger-close').click(function () {
        $('.header__menu').removeClass('header__menu--active')
        $('body').removeClass('fixed-body')
    })

    $(document).click(function (e) {
        if (
            !$(e.target).closest('.header__menu').length &&
            !$(e.target).closest('.burger').length
        ) {
            $('.header__menu').removeClass('header__menu--active')
            $('body').removeClass('fixed-body')
        }
    })

    // Header
    $(window).on('scroll', function () {
        if ($(window).scrollTop() > 0) {
            $('.header').addClass('header--fixed');
        } else {
            $('.header').removeClass('header--fixed');
        }
    });

    // Pagination
    function setProjectsPaginationWidth() {
        const slider = document.querySelector('.projects2__slider');

        if (!slider) return;

        const pagination = slider.querySelector('.swiper-pagination');

        if (!pagination) return;

        const sliderLeft = slider.getBoundingClientRect().left;

        pagination.style.setProperty(
            '--pagination-width',
            `${window.innerWidth - sliderLeft}px`
        );
    }

    setProjectsPaginationWidth();

    window.addEventListener('resize', setProjectsPaginationWidth);

})

// Animation
gsap.registerPlugin(ScrollTrigger);

// Projects
const projectsTl = gsap.timeline({
    scrollTrigger: {
        trigger: ".projects",
        start: window.innerWidth <= 992 ? "top 100px" : "top 150px",
        toggleActions: "play none none none",
    }
});

projectsTl
    .from(".projects__title", {
        yPercent: 100,
        duration: 1.6,
        ease: "power3.out",
    })
    .from(".projects__text", {
        opacity: 0,
        duration: 1,
        ease: "power2.out",
    }, "-=0.8");

